       e^{i(-\vartheta(L/2)))} \Big)  \\
      &\stackrel{\eqref{eq:cor:angle_condition}}{=} \frac{ a_3\sqrt{\kappa(\tfrac{L}{2})^2-\mu}}{\kappa(\tfrac{L}{2})}
      \Re\big( \pm i e^{i\vartheta(L/2))}e^{-i\vartheta(L/2))} \big) \\
      &= 0.
    \end{align*}

\begin{align*}
       W_1(s)^2+W_2(s)^2
       &\stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{w_1(z)^2+w_2(z)^2}{2-k^2}
       \stackrel{\ref{prop:w1w2_orbitlike}.(ii)}{=} 1-\frac{\dn^2(z,k)}{2-k^2}

       \stackrel{\eqref{eq:formulas_dnsncn}}{=}
       \frac{\kappa(s)^2-\mu}{\kappa(s)^2}. \\
     \intertext{The assertion (ii) is true because of}
       W_1'(s)
       &\stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{1}{2-k^2} w_1'(z) \\
       &= \frac{1}{2-k^2}
       \frac{w_1(z)(w_1w_1'+w_2w_2')(z)-w_2(z)(w_1w_2'-w_2w_1')(z)}{(w_1^2+w_2^2)(z)} \\
       &\hspace{-1.2cm}\stackrel{\ref{prop:w1w2_orbitlike}.(ii)-(iv)}{=} \frac{1}{(2-k^2)^{3/2}}
         \frac{k^2\dn(z,k)\cn(z,k)\sn(z,k) W_1(s)- \sqrt{1-k^2}\sqrt{2-k^2}W_2(s)}{W_1(s)^2+W_2(s)^2}
         \\
      &\stackrel{\eqref{eq:formulas_dnsncn}}{=}\frac{4(1-k^2)}{(2-k^2)^2} \frac{\kappa'(s)}{\kappa(s)^3}
      \frac{W_1(s)}{W_1(s)^2+W_2(s)^2} - \frac{\sqrt{1-k^2}}{2-k^2} \frac{W_2(s)}{W_1(s)^2+W_2(s)^2}  \\
      &\stackrel{\ref{prop:W1W2_orbitlike}.(i)}{=} \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} W_1(s)
      - \frac{\sqrt\mu \kappa(s)^2}{2(\kappa(s)^2-\mu)}W_2(s). \\
     \intertext{Similarly, (iii) follows from}
       W_2'(s)
       &= \frac{1}{2-k^2}
       \frac{w_2(z)(w_1w_1'+w_2w_2')(z)+w_1(z)(w_1w_2'-w_2w_1')(z)}{(w_1^2+w_2^2)(z)} \\
       &= \frac{\sqrt\mu \kappa(s)^2}{2(\kappa(s)^2-\mu)}W_1(s) +
       \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} W_2(s). \\
     \intertext{









     The items (iv),(v) follow directly from
     Proposition~\ref{prop:w1w2_orbitlike}~(iv),(v).
     Finally, we set $t:= -s-2s_*+2l\sqrt{2-k^2}K(k)$ so that (vi) results from}
     W_1(s)+iW_2(s)
     &= (w_1+iw_2) \big( -K(k)+\frac{-(t+s_*)+2l\sqrt{2-k^2}K(k)}{\sqrt{2-k^2}} \big) \\
     &= (w_1+iw_2) \big( K(k)-\frac{t+s_*}{\sqrt{2-k^2}} + (2l-2)K(k)\big) \\
     &\stackrel{\ref{prop:w1w2_orbitlike}.(vi)}{=}  (w_1+iw_2)
     \big(K(k)-\frac{t+s_*}{\sqrt{2-k^2}}\big) e^{i(l-1)\Delta\theta_k}  \\
     &\stackrel{\ref{prop:w1w2_orbitlike}.(i)}{=} (-w_1+iw_2) \big(-K(k)+\frac{t+s_*}{\sqrt{2-k^2}}\big)
     e^{i(l-1)\Delta\theta_k}  \\
     &= (-W_1(t)+iW_2(t))  e^{i(l-1)\Delta\theta_k}.
